def apply_input_guards(module):
    import inspect, math, numpy as np
    def battery_guard(b):
        values=(b.lo,b.hi,b.max_kwh,b.eta_c,b.eta_d)
        if not all(math.isfinite(float(x)) for x in values):
            raise ValueError('Battery parameters must be finite')
        if not (0 <= b.lo <= b.hi and b.max_kwh >= 0 and 0 < b.eta_c <= 1 and 0 < b.eta_d <= 1):
            raise ValueError('Invalid physical battery parameters')
    def guarded(original):
        signature=inspect.signature(original)
        def wrapped(*args,**kwargs):
            bound=signature.bind(*args,**kwargs); bound.apply_defaults()
            values=bound.arguments
            b=values.get('battery',values.get('b'))
            if b is not None: battery_guard(b)
            if 'terminal_value' in values:
                t=values['terminal_value']
                if not math.isfinite(float(t)) or t < 0:
                    raise ValueError('Terminal value must be finite nonnegative')
            if original.__name__=='ordinary_cost':
                for name in ('g0','a','price'):
                    x=np.asarray(values[name],dtype=float)
                    if not np.isfinite(x).all() or np.any(x<0):
                        raise ValueError('Settlement inputs must be finite nonnegative')
            return original(*args,**kwargs)
        return wrapped
    for name in ('ordinary_cost','feedback','solve_plan','causal_rollout'):
        setattr(module,name,guarded(getattr(module,name)))
